      prospectingRecords: [],
      leads: [],
      quotes: []
    };

    let state = seedState();

    function currentMonth() {
      return new Date().toISOString().slice(0, 7);
    }

    function today() {
      return new Date().toISOString().slice(0, 10);
    }

    function uid() {
      return Math.random().toString(36).slice(2) + Date.now().toString(36);
    }

    function seedState() {
      const d = today();
      const prospectingRecords = [
