        { id: uid(), date: d, companyId: "smart", vendor: "Hector Castañeda", clientType: "Prospecto nuevo", clientCompany: "Planta electrónica C", contactName: "Jefe de Ingeniería", position: "Ingeniería", phone: "", email: "ing@cliente.com", linkedin: "", service: "Servicio - Instalaciones eléctricas", channels: { email: true, call: true, whatsapp: true, linkedin: false }, result: "Solicitó cotización", generatedLead: true, nextAction: d, priority: "Alta", notes: "Requiere levantamiento." },
        { id: uid(), date: d, companyId: "maqmen", vendor: "Everardo Armenta", clientType: "Cliente existente", clientCompany: "Logística D", contactName: "Operaciones", position: "Operaciones", phone: "", email: "ops@cliente.com", linkedin: "", service: "Renta - Montacargas", channels: { email: true, call: true, whatsapp: true, linkedin: false }, result: "Respondió", generatedLead: true, nextAction: d, priority: "Media", notes: "Urgencia semanal." },
        { id: uid(), date: d, companyId: "energy", vendor: "Oscar Gutierrez", clientType: "Reactivación", clientCompany: "Manufactura E", contactName: "Facilities", position: "Facilities", phone: "", email: "facilities@cliente.com", linkedin: "", service: "Servicio - Pruebas eléctricas", channels: { email: true, call: false, whatsapp: false, linkedin: true }, result: "Reunión agendada", generatedLead: true, nextAction: d, priority: "Media", notes: "Reunión técnica." }
      ];

      const leads = [
        { id: uid(), date: d, companyId: "scr", vendor: "Vincent Rodriguez", client: "Maquiladora médica A", contactName: "Gerente de Mantenimiento", source: "Prospección B2B", stage: "Calificado", interestType: "Servicio", service: "Certificación", nextAction: d, priority: "Alta", notes: "Interés en validación." },
        { id: uid(), date: d, companyId: "smart", vendor: "Hector Castañeda", client: "Planta electrónica C", contactName: "Jefe de Ingeniería", source: "Prospección B2B", stage: "Levantamiento", interestType: "Servicio", service: "Instalaciones eléctricas", nextAction: d, priority: "Alta", notes: "Instalación eléctrica." },
        { id: uid(), date: d, companyId: "maqmen", vendor: "Everardo Armenta", client: "Logística D", contactName: "Operaciones", source: "WhatsApp", stage: "Cotizado", interestType: "Producto", service: "Montacargas renta", nextAction: d, priority: "Media", notes: "Renta montacargas." },
        { id: uid(), date: d, companyId: "energy", vendor: "Oscar Gutierrez", client: "Manufactura E", contactName: "Facilities", source: "Reactivación", stage: "Negociación", interestType: "Servicio", service: "Pruebas eléctricas", nextAction: d, priority: "Media", notes: "Termografía." }
      ];

      const quotes = [
        { id: uid(), date: d, companyId: "scr", vendor: "Marco Garcia", folio: "SCR-2026-001", client: "Laboratorio F", service: "Servicio - Certificación", quoteName: "Certificación ISO 14644 área producción", amount: 420000, currency: "MN", status: "En seguimiento", probability: 50, decisionDate: "", notes: "Pendiente técnico." },
        { id: uid(), date: d, companyId: "smart", vendor: "Ramon Hernandez", folio: "SMART-2026-001", client: "Planta G", service: "Servicio - Instalaciones eléctricas", quoteName: "Instalación eléctrica para maquinaria nueva", amount: 180000, currency: "MN", status: "Negociación", probability: 70, decisionDate: "", notes: "Compras revisando." },
        { id: uid(), date: d, companyId: "maqmen", vendor: "Oscar Alonso", folio: "MAQ-2026-001", client: "Empresa H", service: "Servicio - Maniobras", quoteName: "Maniobra de maquinaria CNC", amount: 95000, currency: "MN", status: "Ganada", probability: 90, decisionDate: d, notes: "Cierre por urgencia." },
        { id: uid(), date: d, companyId: "energy", vendor: "Miguel Zazueta", folio: "ENE-2026-001", client: "Planta I", service: "Servicio - Pruebas eléctricas", quoteName: "Pruebas eléctricas y diagnóstico", amount: 4500, currency: "USD", status: "Enviada", probability: 30, decisionDate: "", notes: "Seguimiento 48h." }
      ];

      return { ...structuredClone(defaultState), prospectingRecords, leads, quotes };
