    async function loadState() {
      try {
        const response = await fetch("../api/api.php?action=load", { cache: "no-store" });
        const payload = await response.json();

        if (!payload.success || !payload.state) {
          return seedState();
        }

        const parsed = payload.state;
        const merged = {
          ...structuredClone(defaultState),
          ...parsed,
          config: { ...defaultState.config, ...(parsed.config || {}) },
          companies: parsed.companies && parsed.companies.length ? parsed.companies : structuredClone(baseCompanies),
          prospectingRecords: parsed.prospectingRecords || [],
          leads: parsed.leads || [],
          quotes: parsed.quotes || []
        };

        merged.companies = merged.companies.map(c => {
          const base = baseCompanies.find(b => b.id === c.id);
          return { ...base, ...c, logo: base ? base.logo : c.logo, services: base ? base.services : c.services };
        });

        return migrateState(merged);
      } catch (error) {
        console.error("No se pudo cargar la base de datos local PHP/SQLite.", error);
        return seedState();
      }
    }

    function migrateState(s) {
      s.leads = (s.leads || []).map(l => ({
        ...l,
        date: l.date || today(),
        contactName: l.contactName || "",
        interestType: l.interestType || serviceToInterestType(l.service || firstService(l.companyId)),
        service: l.service || firstService(l.companyId),
        priority: l.priority || "Media"
      }));
      s.quotes = (s.quotes || []).map((q, idx) => ({
        ...q,
        date: q.date || today(),
        folio: q.folio || `${companyByIdSafe(s, q.companyId).short}-${new Date().getFullYear()}-${String(idx + 1).padStart(3, "0")}`,
        quoteName: q.quoteName || q.service || "Cotización",
        currency: q.currency || "MN",
        service: q.service || firstService(q.companyId)
      }));
      s.prospectingRecords = (s.prospectingRecords || []).map(p => ({
        ...p,
        service: p.service || firstService(p.companyId),
        priority: p.priority || "Media"
      }));
      return s;
    }

    let saveTimer = null;

    function saveState() {
      clearTimeout(saveTimer);
      saveTimer = setTimeout(() => persistState(), 350);
    }

    async function persistState() {
      try {
        const response = await fetch("../api/api.php?action=save", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(state)
        });

        const payload = await response.json();
        if (!payload.success) {
          console.error("Error guardando en SQLite:", payload.error || payload);
        }
      } catch (error) {
        console.error("No se pudo guardar en la base local PHP/SQLite.", error);
      }
    }

    async function resetDatabase() {
      try {
        const response = await fetch("../api/api.php?action=reset", { method: "POST" });
        const payload = await response.json();
        if (!payload.success) {
          console.error("Error restableciendo SQLite:", payload.error || payload);
        }
      } catch (error) {
        console.error("No se pudo restablecer la base local PHP/SQLite.", error);
      }
    }

    function companyByIdSafe(s, id) {
      return (s.companies || baseCompanies).find(c => c.id === id) || baseCompanies[0];
    }

    function companyById(id) {
      return state.companies.find(c => c.id === id) || state.companies[0];
    }

    function firstService(companyId) {
      return (catalogs[companyId] || ["Otro"])[0];
    }

    function serviceOptions(companyId) {
      return (catalogs[companyId] || []).map(s => `<option value="${escapeHtml(s)}">${escapeHtml(s)}</option>`).join("");
    }

    function setServiceOptions(companySelectId, serviceSelectId, selectedValue = null) {
      const companyId = document.getElementById(companySelectId)?.value || state.companies[0].id;
      const el = document.getElementById(serviceSelectId);
      if (!el) return;
      el.innerHTML = serviceOptions(companyId);
      if (selectedValue && Array.from(el.options).some(o => o.value === selectedValue)) el.value = selectedValue;
    }

    function leadServiceOptions(companyId, type) {
      const items = (leadCatalogs[companyId] && leadCatalogs[companyId][type]) ? leadCatalogs[companyId][type] : ["Otros"];
      return items.map(s => `<option value="${escapeHtml(s)}">${escapeHtml(s)}</option>`).join("");
    }

    function setLeadServiceOptions(companySelectId, typeSelectId, serviceSelectId, selectedValue = null) {
      const companyId = document.getElementById(companySelectId)?.value || state.companies[0].id;
      const type = document.getElementById(typeSelectId)?.value || "Servicio";
      const el = document.getElementById(serviceSelectId);
      if (!el) return;
      el.innerHTML = leadServiceOptions(companyId, type);
      if (selectedValue && Array.from(el.options).some(o => o.value === selectedValue)) el.value = selectedValue;
    }

    function serviceToInterestType(service) {
      const value = String(service || "").toLowerCase();
      if (value.startsWith("producto") || value.startsWith("renta")) return "Producto";
      return "Servicio";
    }


    function fmtMoney(value) {
      return new Intl.NumberFormat("es-MX", { style: "currency", currency: "MXN", maximumFractionDigits: 0 }).format(Number(value || 0));
    }

    function fmtCurrency(value, currency) {
      if (currency === "USD") {
        return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(Number(value || 0));
      }
      return fmtMoney(value);
    }

    function fmtNum(value) {
      return new Intl.NumberFormat("es-MX").format(Number(value || 0));
    }

    function pct(value, decimals = 0) {
      if (!Number.isFinite(value)) return "0%";
      return `${value.toFixed(decimals)}%`;
    }

    function clamp(n, min, max) {
      return Math.max(min, Math.min(max, n));
    }

    function val(id) {
      return document.getElementById(id).value;
    }

    function num(id) {
      return Number(document.getElementById(id).value || 0);
    }

    function escapeHtml(str) {
      return String(str ?? "").replace(/[&<>"']/g, m => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" }[m]));
    }

    function getFilters() {
      return {
        companyId: document.getElementById("filterCompany").value,
        period: document.getElementById("filterPeriod").value,
        month: document.getElementById("filterMonth").value || currentMonth()
      };
    }

    function dateToWeekInMonth(dateStr) {
      if (!dateStr) return "semana-1";
      const day = Number(dateStr.slice(8, 10));
      if (day <= 7) return "semana-1";
      if (day <= 14) return "semana-2";
      if (day <= 21) return "semana-3";
      if (day <= 28) return "semana-4";
      return "semana-5";
    }

    function labelPeriod(p) {
      return (p || "").replace("semana-", "Semana ");
    }

    function quoteAmountMxn(q) {
      const amount = Number(q.amount || 0);
      return q.currency === "USD" ? amount * Number(state.config.exchangeRateUsdMxn || 0) : amount;
    }

    function filteredCompanies() {
      const f = getFilters();
      return f.companyId === "all" ? state.companies : state.companies.filter(c => c.id === f.companyId);
    }

    function inFilterDate(dateStr) {
      const f = getFilters();
      if (!dateStr || !dateStr.startsWith(f.month)) return false;
      return f.period === "all" || dateToWeekInMonth(dateStr) === f.period;
    }

    function filteredProspectingRecords() {
      const f = getFilters();
      return state.prospectingRecords.filter(r => {
        const companyOk = f.companyId === "all" || r.companyId === f.companyId;
        return companyOk && inFilterDate(r.date);
      });
    }

    function filteredLeads() {
      const f = getFilters();
      return state.leads.filter(r => {
        const companyOk = f.companyId === "all" || r.companyId === f.companyId;
        return companyOk && inFilterDate(r.date);
      });
    }

    function filteredQuotes() {
      const f = getFilters();
      return state.quotes.filter(r => {
        const companyOk = f.companyId === "all" || r.companyId === f.companyId;
        return companyOk && inFilterDate(r.date);
      });
    }

    function periodMultiplier() {
      const f = getFilters();
      return f.period === "all" ? state.config.weeksPerMonth : 1;
    }

    function aggregateProspecting(records, companyIds = null) {
      const base = {
        records: 0,
        emails: 0,
        calls: 0,
        whatsapps: 0,
        linkedin: 0,
        responses: 0,
        noResponses: 0,
        interested: 0,
        quoteRequests: 0,
        meetings: 0,
        generatedLeads: 0
      };
      records.forEach(r => {
        if (companyIds && !companyIds.includes(r.companyId)) return;
        base.records += 1;
        if (r.channels?.email) base.emails += 1;
        if (r.channels?.call) base.calls += 1;
        if (r.channels?.whatsapp) base.whatsapps += 1;
        if (r.channels?.linkedin) base.linkedin += 1;
        const result = r.result || "Sin respuesta";
        if (result === "Sin respuesta") base.noResponses += 1;
        if (["Respondió", "Interesado", "Solicitó cotización", "Reunión agendada"].includes(result)) base.responses += 1;
        if (result === "Interesado") base.interested += 1;
        if (result === "Solicitó cotización") base.quoteRequests += 1;
        if (result === "Reunión agendada") base.meetings += 1;
        if (r.generatedLead === true || r.generatedLead === "yes") base.generatedLeads += 1;
      });
      return base;
    }

    function aggregateLeads(leads, companyIds = null) {
      const base = { total: 0, qualified: 0, meetings: 0, won: 0, lost: 0 };
      leads.forEach(l => {
        if (companyIds && !companyIds.includes(l.companyId)) return;
        base.total += 1;
        if (["Calificado", "Levantamiento", "Cotizado", "Negociación", "Ganado"].includes(l.stage)) base.qualified += 1;
        if (l.stage === "Levantamiento") base.meetings += 1;
        if (l.stage === "Ganado") base.won += 1;
        if (l.stage === "Perdido") base.lost += 1;
      });
      return base;
    }

    function aggregateQuotes(quotes, companyIds = null) {
      const base = { total: 0, quotedAmount: 0, closedSales: 0, closedAmount: 0, lostQuotes: 0, open: 0, openAmount: 0 };
      quotes.forEach(q => {
        if (companyIds && !companyIds.includes(q.companyId)) return;
        const mxn = quoteAmountMxn(q);
        base.total += 1;
        base.quotedAmount += mxn;
        if (q.status === "Ganada") {
          base.closedSales += 1;
          base.closedAmount += mxn;
        } else if (q.status === "Perdida") {
          base.lostQuotes += 1;
        } else {
          base.open += 1;
          base.openAmount += mxn;
        }
      });
      return base;
    }

    function targetsFor(companies = filteredCompanies()) {
      const weeks = periodMultiplier();
      const monthlyGoal = companies.reduce((s, c) => s + Number(c.monthlyGoal || 0), 0);
      const vendorCount = companies.reduce((s, c) => s + c.vendors.length, 0);
      return {
        monthlyGoal,
        pipelineRequired: monthlyGoal / (state.config.closeRate / 100),
        leads: companies.length * state.config.leadTargetWeekly * weeks,
        quotes: companies.length * state.config.quoteTargetWeekly * weeks,
        adBudget: companies.length * state.config.adBudgetWeekly * weeks,
        dailyEmails: vendorCount * state.config.dailyPersonalizedEmails,
        weeklyEmails: vendorCount * state.config.dailyPersonalizedEmails * state.config.workDaysPerWeek,
        monthlyEmails: vendorCount * state.config.dailyPersonalizedEmails * state.config.workDaysPerWeek * weeks
      };
    }

    function logoName(c) {
      return `<img class="company-logo-small" src="${c.logo}" alt="${escapeHtml(c.name)}">${escapeHtml(c.name)}`;
    }

    function statusBadge(value, target) {
      const ratio = target ? value / target : 0;
      if (ratio >= 1) return `<span class="badge success">Cumplido</span>`;
      if (ratio >= .75) return `<span class="badge warning">En riesgo</span>`;
      return `<span class="badge danger">Crítico</span>`;
    }

    function renderAll() {
      document.getElementById("exchangeRateView").value = `${fmtMoney(state.config.exchangeRateUsdMxn)}`;
      renderDashboard();
      renderCompanies();
      renderProspecting();
      renderAutoWeekly();
      renderLeads();
      renderQuotes();
      renderVendors();
      renderAds();
      renderConfig();
      saveState();
    }

    function renderDashboard() {
      const companies = filteredCompanies();
      const ids = companies.map(c => c.id);
      const pRecords = filteredProspectingRecords();
      const leads = filteredLeads();
      const quotes = filteredQuotes();
      const pros = aggregateProspecting(pRecords, ids);
      const leadAgg = aggregateLeads(leads, ids);
      const quoteAgg = aggregateQuotes(quotes, ids);
      const targets = targetsFor(companies);

      const salesCoverage = targets.monthlyGoal ? quoteAgg.closedAmount / targets.monthlyGoal * 100 : 0;
      const pipelineCoverage = targets.pipelineRequired ? quoteAgg.quotedAmount / targets.pipelineRequired * 100 : 0;
      const conversion = quoteAgg.total ? quoteAgg.closedSales / quoteAgg.total * 100 : 0;
      const leadToQuote = leadAgg.total ? quoteAgg.total / leadAgg.total * 100 : 0;
      const responseRate = pros.records ? pros.responses / pros.records * 100 : 0;
      const emailCompliance = targets.monthlyEmails ? pros.emails / targets.monthlyEmails * 100 : 0;

      const kpis = [
        ["Venta cerrada MXN", fmtMoney(quoteAgg.closedAmount), `${pct(salesCoverage)} de ${fmtMoney(targets.monthlyGoal)}`, quoteAgg.closedAmount, targets.monthlyGoal],
        ["Pipeline cotizado MXN", fmtMoney(quoteAgg.quotedAmount), `${pct(pipelineCoverage)} de cobertura requerida`, quoteAgg.quotedAmount, targets.pipelineRequired],
        ["Leads CRM", fmtNum(leadAgg.total), `Meta del periodo: ${fmtNum(targets.leads)}`, leadAgg.total, targets.leads],
        ["Cotizaciones", fmtNum(quoteAgg.total), `Meta del periodo: ${fmtNum(targets.quotes)}`, quoteAgg.total, targets.quotes],
        ["Correos B2B", fmtNum(pros.emails), `Meta estimada: ${fmtNum(targets.monthlyEmails)}`, pros.emails, targets.monthlyEmails],
        ["Tasa de respuesta B2B", pct(responseRate, 1), `${fmtNum(pros.responses)} respuestas de ${fmtNum(pros.records)} contactos`, responseRate, 15],
        ["Conversión cotización", pct(conversion, 1), `Objetivo del modelo: ${state.config.closeRate}%`, conversion, state.config.closeRate],
        ["Lead a cotización", pct(leadToQuote, 1), "Cotizaciones / leads CRM", leadToQuote, 50]
      ];

      document.getElementById("kpiCards").innerHTML = kpis.map(([label, value, sub, current, target]) => {
        const ratio = target ? current / target : 0;
        const cls = ratio >= 1 ? "success" : ratio >= .75 ? "warning" : "danger";
        const txt = ratio >= 1 ? "OK" : ratio >= .75 ? "Atención" : "Acción";
        return `
          <div class="card kpi">
            <span class="badge ${cls}">${txt}</span>
            <div class="label">${label}</div>
            <div class="value">${value}</div>
            <div class="sub">${sub}</div>
            <div class="progress"><span style="width:${clamp(ratio * 100, 2, 100)}%"></span></div>
          </div>`;
      }).join("");

      renderRanking(companies);
      renderExecutiveSummary(quoteAgg, leadAgg, pros, targets, conversion, pipelineCoverage, salesCoverage, responseRate, emailCompliance);

      drawSalesChart(companies);
      drawFunnelChart("chartFunnel", [
        { label: "Prospección B2B", value: pros.records },
        { label: "Respuestas", value: pros.responses },
        { label: "Leads CRM", value: leadAgg.total },
        { label: "Cotizaciones", value: quoteAgg.total },
        { label: "Ventas", value: quoteAgg.closedSales }
      ]);
      drawProspectingChart(companies);
      drawPipelineChart(companies);
    }

    function renderRanking(companies) {
      const rows = companies.map(c => {
        const p = aggregateProspecting(filteredProspectingRecords(), [c.id]);
        const q = aggregateQuotes(filteredQuotes(), [c.id]);
        const salesPct = c.monthlyGoal ? q.closedAmount / c.monthlyGoal * 100 : 0;
        const respPct = p.records ? p.responses / p.records * 100 : 0;
        return { c, p, q, salesPct, respPct };
      }).sort((a,b) => b.salesPct - a.salesPct);

      document.getElementById("rankingTable").innerHTML = rows.map(r => `
        <tr>
          <td>${logoName(r.c)}</td>
          <td class="right money">${fmtMoney(r.q.closedAmount)}</td>
          <td class="right">${pct(r.salesPct)}</td>
          <td class="right money">${fmtMoney(r.q.quotedAmount)}</td>
          <td class="right">${fmtNum(r.p.emails)}</td>
          <td class="right">${pct(r.respPct, 1)}</td>
        </tr>
      `).join("");
    }

    function renderExecutiveSummary(quoteAgg, leadAgg, pros, targets, conversion, pipelineCoverage, salesCoverage, responseRate, emailCompliance) {
      const headline = document.getElementById("execHeadline");
      const detail = document.getElementById("execDetail");
      const list = document.getElementById("execChecklist");

      let condition = "El plan requiere disciplina diaria en prospección, CRM y cotizaciones.";
      if (salesCoverage >= 100) condition = "El objetivo de venta del periodo está cumplido.";
      else if (pipelineCoverage >= 100 && conversion >= state.config.closeRate && emailCompliance >= 80) condition = "La operación muestra condiciones suficientes para alcanzar la meta si se mantiene la ejecución.";
      else if (pipelineCoverage < 75) condition = "El principal riesgo es falta de pipeline cotizado suficiente.";
      else if (emailCompliance < 75) condition = "El principal riesgo es incumplimiento en prospección B2B diaria.";

      headline.textContent = condition;
      detail.textContent = `Venta actual: ${fmtMoney(quoteAgg.closedAmount)} contra meta de ${fmtMoney(targets.monthlyGoal)}. Pipeline: ${fmtMoney(quoteAgg.quotedAmount)} contra requerido de ${fmtMoney(targets.pipelineRequired)}. Correos B2B registrados: ${fmtNum(pros.emails)} de ${fmtNum(targets.monthlyEmails)} meta estimada. Tipo de cambio USD/MN: ${state.config.exchangeRateUsdMxn}.`;

      const actions = [];
      if (pros.emails < targets.monthlyEmails) actions.push(`Aumentar prospección: faltan ${fmtNum(Math.max(0, targets.monthlyEmails - pros.emails))} correos personalizados para la meta del periodo.`);
      if (responseRate < 15) actions.push(`Mejorar calidad del mensaje: tasa de respuesta B2B actual de ${pct(responseRate, 1)}.`);
      if (leadAgg.total < targets.leads) actions.push(`Generar más leads CRM: faltan ${fmtNum(Math.max(0, targets.leads - leadAgg.total))} leads para el objetivo del periodo.`);
      if (quoteAgg.total < targets.quotes) actions.push(`Acelerar cotizaciones: faltan ${fmtNum(Math.max(0, targets.quotes - quoteAgg.total))} cotizaciones.`);
      if (quoteAgg.quotedAmount < targets.pipelineRequired) actions.push(`Subir valor cotizado: faltan ${fmtMoney(Math.max(0, targets.pipelineRequired - quoteAgg.quotedAmount))} de pipeline.`);
      if (conversion < state.config.closeRate) actions.push(`Elevar cierre: conversión actual de ${pct(conversion, 1)} contra objetivo de ${state.config.closeRate}%.`);
      if (!actions.length) actions.push("Mantener ritmo, reforzar seguimiento 5x y proteger oportunidades de alto valor.");

      list.innerHTML = actions.map(a => `<li>${a}</li>`).join("");
    }

    function renderCompanies() {
      document.getElementById("companyCards").innerHTML = state.companies.map(c => {
        const q = aggregateQuotes(filteredQuotes(), [c.id]);
        const p = aggregateProspecting(filteredProspectingRecords(), [c.id]);
        const l = aggregateLeads(filteredLeads(), [c.id]);
        const pipelineRequired = c.monthlyGoal / (state.config.closeRate / 100);
        const weeklyGoal = c.monthlyGoal / state.config.weeksPerMonth;
        const weeklyPipeline = pipelineRequired / state.config.weeksPerMonth;
        const avgQuoteNeeded = pipelineRequired / (state.config.quoteTargetWeekly * state.config.weeksPerMonth);
        const emailWeeklyTarget = c.vendors.length * state.config.dailyPersonalizedEmails * state.config.workDaysPerWeek;
        const salesPct = c.monthlyGoal ? q.closedAmount / c.monthlyGoal * 100 : 0;
        const emailPct = emailWeeklyTarget ? p.emails / (emailWeeklyTarget * periodMultiplier()) * 100 : 0;

        return `
          <div class="card">
            <div class="card-body">
              <div class="company-card-grid">
                <div class="company-logo-box"><img src="${c.logo}" alt="${escapeHtml(c.name)}"></div>
                <div>
                  <h3 style="margin:0 0 10px; font-size:22px;">${escapeHtml(c.name)}</h3>
                  <div class="pill-list">${c.services.map(s => `<span class="pill">${escapeHtml(s)}</span>`).join("")}</div>
                </div>
              </div>
              <div class="metric-row">
                <div class="mini"><span>Meta mensual</span><strong>${fmtMoney(c.monthlyGoal)}</strong></div>
                <div class="mini"><span>Meta semanal</span><strong>${fmtMoney(weeklyGoal)}</strong></div>
                <div class="mini"><span>Pipeline requerido</span><strong>${fmtMoney(pipelineRequired)}</strong></div>
                <div class="mini"><span>Pipeline semanal</span><strong>${fmtMoney(weeklyPipeline)}</strong></div>
              </div>
              <div class="metric-row">
                <div class="mini"><span>Correos/vendedor/día</span><strong>${state.config.dailyPersonalizedEmails}</strong></div>
                <div class="mini"><span>Correos/empresa/semana</span><strong>${fmtNum(emailWeeklyTarget)}</strong></div>
                <div class="mini"><span>Leads CRM</span><strong>${fmtNum(l.total)}</strong></div>
                <div class="mini"><span>Cotizaciones</span><strong>${fmtNum(q.total)}</strong></div>
              </div>
              <div class="metric-row">
                <div class="mini"><span>Ticket cotizado necesario</span><strong>${fmtMoney(avgQuoteNeeded)}</strong></div>
                <div class="mini"><span>Venta registrada</span><strong>${fmtMoney(q.closedAmount)}</strong></div>
                <div class="mini"><span>Correos B2B registrados</span><strong>${fmtNum(p.emails)}</strong></div>
                <div class="mini"><span>Tasa respuesta B2B</span><strong>${pct(p.records ? p.responses / p.records * 100 : 0, 1)}</strong></div>
              </div>
              <div style="margin-top:14px;">
                <div class="small muted">Cumplimiento de venta</div>
                <div class="progress"><span style="width:${clamp(salesPct,2,100)}%; background:${c.color};"></span></div>
              </div>
              <div style="margin-top:14px;">
                <div class="small muted">Cumplimiento de correos personalizados B2B</div>
                <div class="progress"><span style="width:${clamp(emailPct,2,100)}%; background:${c.color};"></span></div>
              </div>
              <div style="margin-top:14px;">
                <strong>Vendedores</strong>
                <div class="pill-list" style="margin-top:10px;">${c.vendors.map(v => `<span class="pill">${escapeHtml(v)}</span>`).join("")}</div>
              </div>
            </div>
          </div>`;
      }).join("");
    }

    function renderProspecting() {
      updateVendorSelect("pCompany", "pVendor");
      setServiceOptions("pCompany", "pService");
      const records = filteredProspectingRecords();
      const companies = filteredCompanies();
      const ids = companies.map(c => c.id);
      const p = aggregateProspecting(records, ids);
      const targets = targetsFor(companies);
      const responseRate = p.records ? p.responses / p.records * 100 : 0;

      const kpis = [
        ["Correos personalizados", fmtNum(p.emails), `Meta periodo: ${fmtNum(targets.monthlyEmails)}`, p.emails, targets.monthlyEmails],
        ["Contactos B2B totales", fmtNum(p.records), "Registros capturados en bitácora", p.records, targets.monthlyEmails],
        ["Respuestas obtenidas", fmtNum(p.responses), `Tasa respuesta: ${pct(responseRate,1)}`, responseRate, 15],
        ["Leads generados", fmtNum(p.generatedLeads), "Desde prospección B2B hacia CRM", p.generatedLeads, targets.leads * .35],
        ["Llamadas realizadas", fmtNum(p.calls), "Complemento a correo personalizado", p.calls, p.emails * .4],
        ["WhatsApps enviados", fmtNum(p.whatsapps), "Seguimiento directo", p.whatsapps, p.emails * .25],
        ["LinkedIn", fmtNum(p.linkedin), "Conexiones o mensajes", p.linkedin, p.emails * .25],
        ["Sin respuesta", fmtNum(p.noResponses), "Requiere secuencia de seguimiento", p.responses, Math.max(1, p.noResponses)]
      ];

      document.getElementById("prospectingKpis").innerHTML = kpis.map(([label, value, sub, current, target]) => {
        const ratio = target ? current / target : 0;
        const cls = ratio >= 1 ? "success" : ratio >= .75 ? "warning" : "danger";
        const txt = ratio >= 1 ? "OK" : ratio >= .75 ? "Atención" : "Acción";
        return `
          <div class="card kpi">
            <span class="badge ${cls}">${txt}</span>
            <div class="label">${label}</div>
            <div class="value">${value}</div>
            <div class="sub">${sub}</div>
            <div class="progress"><span style="width:${clamp(ratio*100,2,100)}%"></span></div>
          </div>`;
      }).join("");

      document.getElementById("prospectingTable").innerHTML = [...records].sort((a,b) => (b.date || "").localeCompare(a.date || "")).map(r => {
        const c = companyById(r.companyId);
        const channels = [];
        if (r.channels?.email) channels.push("Correo");
        if (r.channels?.call) channels.push("Llamada");
        if (r.channels?.whatsapp) channels.push("WhatsApp");
        if (r.channels?.linkedin) channels.push("LinkedIn");
        return `
          <tr>
            <td>${r.date || ""}</td>
            <td>${logoName(c)}</td>
            <td>${escapeHtml(r.vendor)}</td>
            <td>${escapeHtml(r.clientCompany)}</td>
            <td>${escapeHtml(r.contactName || "Sin contacto")}<br><span class="small muted">${escapeHtml(r.email || "")} ${escapeHtml(r.phone || "")}</span></td>
            <td>${escapeHtml(r.service || "")}</td>
            <td>${channels.map(ch => `<span class="badge info">${ch}</span>`).join(" ")}</td>
            <td>${resultBadge(r.result)}</td>
            <td><button class="btn danger small" onclick="deleteProspecting('${r.id}')">Eliminar</button></td>
          </tr>`;
      }).join("");

      drawProspectingChannels(records);
      drawVendorEmails(records, companies);
      drawResponseRate(companies, records);
    }

    function resultBadge(result) {
      const cls = {
        "Sin respuesta": "dark",
        "Respondió": "info",
        "Interesado": "success",
        "Solicitó cotización": "warning",
        "Reunión agendada": "violet",
        "No interesado": "danger",
        "Contacto incorrecto": "danger"
      }[result] || "dark";
      return `<span class="badge ${cls}">${escapeHtml(result)}</span>`;
    }

    function renderAutoWeekly() {
      const summaries = buildWeeklySummaries();
      const totals = summaries.reduce((acc, r) => {
        acc.prospecting += r.prospecting;
        acc.emails += r.emails;
        acc.calls += r.calls;
        acc.whatsapps += r.whatsapps;
        acc.linkedin += r.linkedin;
        acc.responses += r.responses;
        acc.leads += r.leads;
        acc.quotes += r.quotes;
        acc.quotedAmount += r.quotedAmount;
        acc.closedSales += r.closedSales;
        acc.closedAmount += r.closedAmount;
        return acc;
      }, { prospecting:0, emails:0, calls:0, whatsapps:0, linkedin:0, responses:0, leads:0, quotes:0, quotedAmount:0, closedSales:0, closedAmount:0 });

      const companies = filteredCompanies();
      const targets = targetsFor(companies);
      const kpis = [
        ["Prospección", fmtNum(totals.prospecting), "Contactos registrados", totals.prospecting, targets.monthlyEmails],
        ["Correos", fmtNum(totals.emails), `Meta: ${fmtNum(targets.monthlyEmails)}`, totals.emails, targets.monthlyEmails],
        ["Leads CRM", fmtNum(totals.leads), `Meta: ${fmtNum(targets.leads)}`, totals.leads, targets.leads],
        ["Cotizaciones", fmtNum(totals.quotes), `Meta: ${fmtNum(targets.quotes)}`, totals.quotes, targets.quotes],
        ["Monto cotizado MXN", fmtMoney(totals.quotedAmount), `Requerido: ${fmtMoney(targets.pipelineRequired)}`, totals.quotedAmount, targets.pipelineRequired],
        ["Monto cerrado MXN", fmtMoney(totals.closedAmount), `Meta: ${fmtMoney(targets.monthlyGoal)}`, totals.closedAmount, targets.monthlyGoal],
        ["Respuestas", fmtNum(totals.responses), `Tasa: ${pct(totals.prospecting ? totals.responses / totals.prospecting * 100 : 0, 1)}`, totals.responses, totals.prospecting * .15],
        ["Cierres", fmtNum(totals.closedSales), "Cotizaciones ganadas", totals.closedSales, totals.quotes * (state.config.closeRate / 100)]
      ];

      document.getElementById("autoWeeklyKpis").innerHTML = kpis.map(([label, value, sub, current, target]) => {
        const ratio = target ? current / target : 0;
        const cls = ratio >= 1 ? "success" : ratio >= .75 ? "warning" : "danger";
        return `
          <div class="card kpi">
            <span class="badge ${cls}">${ratio >= 1 ? "OK" : ratio >= .75 ? "Atención" : "Acción"}</span>
            <div class="label">${label}</div>
            <div class="value">${value}</div>
            <div class="sub">${sub}</div>
            <div class="progress"><span style="width:${clamp(ratio*100,2,100)}%"></span></div>
          </div>`;
      }).join("");

      document.getElementById("autoWeeklyTable").innerHTML = summaries.map(r => {
        const c = companyById(r.companyId);
        return `
          <tr>
            <td>${logoName(c)}</td>
            <td>${r.month}</td>
            <td>${labelPeriod(r.period)}</td>
            <td class="right">${fmtNum(r.prospecting)}</td>
            <td class="right">${fmtNum(r.emails)}</td>
            <td class="right">${fmtNum(r.calls)}</td>
            <td class="right">${fmtNum(r.whatsapps)}</td>
            <td class="right">${fmtNum(r.linkedin)}</td>
            <td class="right">${fmtNum(r.responses)}</td>
            <td class="right">${fmtNum(r.leads)}</td>
            <td class="right">${fmtNum(r.quotes)}</td>
            <td class="right money">${fmtMoney(r.quotedAmount)}</td>
            <td class="right">${fmtNum(r.closedSales)}</td>
            <td class="right money">${fmtMoney(r.closedAmount)}</td>
          </tr>`;
      }).join("");
    }

    function buildWeeklySummaries() {
      const f = getFilters();
      const weeks = f.period === "all" ? ["semana-1", "semana-2", "semana-3", "semana-4", "semana-5"] : [f.period];
      const companies = filteredCompanies();
      const rows = [];
      companies.forEach(c => {
        weeks.forEach(period => {
          const pRecords = state.prospectingRecords.filter(r => r.companyId === c.id && (r.date || "").startsWith(f.month) && dateToWeekInMonth(r.date) === period);
          const lRecords = state.leads.filter(r => r.companyId === c.id && (r.date || "").startsWith(f.month) && dateToWeekInMonth(r.date) === period);
          const qRecords = state.quotes.filter(r => r.companyId === c.id && (r.date || "").startsWith(f.month) && dateToWeekInMonth(r.date) === period);
          const p = aggregateProspecting(pRecords, [c.id]);
          const l = aggregateLeads(lRecords, [c.id]);
          const q = aggregateQuotes(qRecords, [c.id]);
          rows.push({
            companyId: c.id,
            month: f.month,
            period,
            prospecting: p.records,
            emails: p.emails,
            calls: p.calls,
            whatsapps: p.whatsapps,
            linkedin: p.linkedin,
            responses: p.responses,
            leads: l.total,
            qualified: l.qualified,
            quotes: q.total,
            quotedAmount: q.quotedAmount,
            closedSales: q.closedSales,
            closedAmount: q.closedAmount
          });
        });
      });
      return rows;
    }

    function renderLeads() {
      updateVendorSelect("lCompany", "lVendor");
      setLeadServiceOptions("lCompany", "lInterestType", "lService");
      const stages = ["Nuevo", "Contactado", "Calificado", "Levantamiento", "Cotizado", "Negociación", "Ganado", "Perdido"];
      const leads = filteredLeads();
      document.getElementById("kanban").innerHTML = stages.map(stage => {
        const items = leads.filter(l => l.stage === stage);
        return `<div class="lane">
          <h4>${stage} <span class="badge info" style="float:right;">${items.length}</span></h4>
          ${items.map(l => {
            const c = companyById(l.companyId);
            return `<div class="lead-card">
              <strong><span class="company-dot" style="background:${c.color}"></span>${escapeHtml(l.client)}</strong>
              <p>${escapeHtml(l.contactName || "Sin contacto")} · ${escapeHtml(l.vendor)}</p>
              <p>${escapeHtml(l.interestType || "")} · ${escapeHtml(l.service || "")}</p>
              <p style="margin-top:7px;"><button class="btn danger small" onclick="deleteLead('${l.id}')">Eliminar</button></p>
            </div>`;
          }).join("")}
        </div>`;
      }).join("");

      document.getElementById("leadTable").innerHTML = leads.map(l => {
        const c = companyById(l.companyId);
        return `
          <tr>
            <td>${l.date || ""}</td>
            <td>${logoName(c)}</td>
            <td>${escapeHtml(l.vendor)}</td>
            <td>${escapeHtml(l.client)}</td>
            <td>${escapeHtml(l.contactName || "")}</td>
            <td>${escapeHtml(l.interestType || "")}</td>
            <td>${escapeHtml(l.service || "")}</td>
            <td>${escapeHtml(l.stage || "")}</td>
            <td><button class="btn danger small" onclick="deleteLead('${l.id}')">Eliminar</button></td>
          </tr>`;
      }).join("");

      drawStageChart(leads);
    }

    function renderQuotes() {
      updateVendorSelect("qCompany", "qVendor");
      setServiceOptions("qCompany", "qService");
      const quotes = filteredQuotes();
      const total = quotes.reduce((s, q) => s + quoteAmountMxn(q), 0);
      const won = quotes.filter(q => q.status === "Ganada").reduce((s, q) => s + quoteAmountMxn(q), 0);
      const openQuotes = quotes.filter(q => !["Ganada","Perdida"].includes(q.status));
      const open = openQuotes.length;
      const openAmount = openQuotes.reduce((s, q) => s + quoteAmountMxn(q), 0);

      document.getElementById("quoteKpis").innerHTML = [
        ["Total cotizado MXN", fmtMoney(total)],
        ["Pipeline abierto MXN", fmtMoney(openAmount)],
        ["Ganado MXN", fmtMoney(won)],
        ["Abiertas", fmtNum(open)]
      ].map(([label, value]) => `<div class="card kpi" style="min-height:110px; box-shadow:none;"><div class="label">${label}</div><div class="value" style="font-size:22px;">${value}</div></div>`).join("");

      document.getElementById("quoteTable").innerHTML = quotes.map(q => {
        const c = companyById(q.companyId);
        return `<tr>
          <td>${q.date || ""}</td>
          <td>${logoName(c)}</td>
          <td>${escapeHtml(q.vendor)}</td>
          <td>${escapeHtml(q.folio || "")}</td>
          <td>${escapeHtml(q.client)}</td>
          <td>${escapeHtml(q.service || "")}</td>
          <td>${escapeHtml(q.quoteName || "")}</td>
          <td class="right money">${fmtCurrency(q.amount, q.currency)}</td>
          <td>${escapeHtml(q.currency || "MN")}</td>
          <td class="right money">${fmtMoney(quoteAmountMxn(q))}</td>
          <td>${quoteStatusBadge(q.status)}</td>
          <td><button class="btn danger small" onclick="deleteQuote('${q.id}')">Eliminar</button></td>
        </tr>`;
      }).join("");
      drawQuotesChart(quotes);
    }

    function quoteStatusBadge(status) {
      const map = { "Ganada": "success", "Perdida": "danger", "Negociación": "warning", "En seguimiento": "info", "Enviada": "violet" };
      return `<span class="badge ${map[status] || "info"}">${escapeHtml(status)}</span>`;
    }

