      const rows = [];
      state.companies.forEach(c => {
        const perLead = Math.ceil(state.config.leadTargetWeekly / c.vendors.length);
        const perQuote = Math.ceil(state.config.quoteTargetWeekly / c.vendors.length);
        const weeklyEmails = state.config.dailyPersonalizedEmails * state.config.workDaysPerWeek;
        const monthlySales = c.monthlyGoal / c.vendors.length;
        c.vendors.forEach(v => {
          rows.push(`<tr>
            <td>${logoName(c)}</td>
            <td>${escapeHtml(v)}</td>
            <td class="right">${state.config.dailyPersonalizedEmails}</td>
            <td class="right">${weeklyEmails}</td>
            <td class="right">${perLead}</td>
            <td class="right">${perQuote}</td>
            <td class="right money">${fmtMoney(monthlySales)}</td>
          </tr>`);
        });
      });
      document.getElementById("vendorQuotaTable").innerHTML = rows.join("");

      document.getElementById("vendorDirectory").innerHTML = state.companies.map(c => `
        <div class="card" style="box-shadow:none; margin-bottom:12px;">
          <div class="card-body company-card-grid">
            <div class="company-logo-box"><img src="${c.logo}" alt="${escapeHtml(c.name)}"></div>
            <div>
              <h3 style="margin:0 0 10px;">${escapeHtml(c.name)}</h3>
              <div class="pill-list">${c.vendors.map(v => `<span class="pill">${escapeHtml(v)}</span>`).join("")}</div>
            </div>
          </div>
        </div>
      `).join("");
      drawVendorsChart();
    }

    function renderAds() {
      document.getElementById("keywordBlocks").innerHTML = state.companies.map(c => `
        <div style="margin-bottom:20px;">
          <div style="display:flex; align-items:center; gap:10px; margin-bottom:10px;">
            <img src="${c.logo}" alt="${escapeHtml(c.name)}" style="width:90px; height:50px; object-fit:contain; border:1px solid var(--line); border-radius:12px; padding:5px;">
            <h3 style="margin:0;">${escapeHtml(c.name)}</h3>
          </div>
          <div class="pill-list">${c.keywords.map(k => `<span class="pill">${escapeHtml(k)}</span>`).join("")}</div>
        </div>
      `).join("");
      document.getElementById("negativeKeywords").innerHTML = negativeKeywords.map(k => `<span class="pill">${escapeHtml(k)}</span>`).join("");
      drawAdsChart();
    }

