    function updateVendorSelect(companySelectId, vendorSelectId) {
      const companyId = document.getElementById(companySelectId)?.value || state.companies[0].id;
      const c = companyById(companyId);
      const vendorSelect = document.getElementById(vendorSelectId);
      if (!vendorSelect) return;
