    function deleteProspecting(id) {
      if (!confirm("¿Eliminar este registro de prospección?")) return;
      state.prospectingRecords = state.prospectingRecords.filter(r => r.id !== id);
      renderAll();
    }

    function deleteLead(id) {
      if (!confirm("¿Eliminar este lead?")) return;
      state.leads = state.leads.filter(l => l.id !== id);
      renderAll();
    }

    function deleteQuote(id) {
      if (!confirm("¿Eliminar esta cotización?")) return;
      state.quotes = state.quotes.filter(q => q.id !== id);
      renderAll();
    }

    function drawBase(canvasId) {
      const canvas = document.getElementById(canvasId);
      if (!canvas) return null;
      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0) return null;
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      const ctx = canvas.getContext("2d");
      ctx.scale(dpr, dpr);
      ctx.clearRect(0, 0, rect.width, rect.height);
      return { canvas, ctx, w: rect.width, h: rect.height };
    }

    function roundRect(ctx, x, y, width, height, radius, fill, stroke) {
      const r = Math.min(radius, Math.abs(width) / 2, Math.abs(height) / 2);
      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.arcTo(x + width, y, x + width, y + height, r);
      ctx.arcTo(x + width, y + height, x, y + height, r);
      ctx.arcTo(x, y + height, x, y, r);
      ctx.arcTo(x, y, x + width, y, r);
      ctx.closePath();
      if (fill) ctx.fill();
      if (stroke) ctx.stroke();
    }

    function drawAxes(ctx, w, h, pad) {
      ctx.strokeStyle = "#e2e8f0";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(pad, pad);
      ctx.lineTo(pad, h - pad);
      ctx.lineTo(w - pad, h - pad);
      ctx.stroke();
    }

    function drawBarChart(canvasId, labels, values, targets = [], colors = []) {
      const base = drawBase(canvasId);
      if (!base) return;
      const { ctx, w, h } = base;
      const pad = 45;
      const max = Math.max(1, ...values, ...targets) * 1.18;
      const group = (w - pad * 2) / Math.max(1, labels.length);
      const barW = group * .42;
      drawAxes(ctx, w, h, pad);
      ctx.font = "12px Inter, Arial";
      labels.forEach((label, i) => {
        const x = pad + group * i + group / 2;
        const barH = values[i] / max * (h - pad * 2);
        const y = h - pad - barH;
        ctx.fillStyle = colors[i] || "#0f6fbf";
        roundRect(ctx, x - barW / 2, y, barW, Math.max(2, barH), 8, true);
        if (targets[i]) {
          const ty = h - pad - (targets[i] / max) * (h - pad * 2);
          ctx.strokeStyle = "#d97706";
          ctx.setLineDash([5,4]);
          ctx.beginPath();
          ctx.moveTo(x - barW*.8, ty);
          ctx.lineTo(x + barW*.8, ty);
          ctx.stroke();
          ctx.setLineDash([]);
        }
        ctx.fillStyle = "#475569";
        ctx.textAlign = "center";
        ctx.fillText(label, x, h - 16);
      });
    }

    function drawHorizontalBarChart(canvasId, labels, values, targets = [], colors = []) {
      const base = drawBase(canvasId);
      if (!base) return;
      const { ctx, w, h } = base;
      const pad = 28;
      const labelW = 128;
      const max = Math.max(1, ...values, ...targets) * 1.15;
      const rowH = (h - pad * 2) / Math.max(1, labels.length);
      ctx.font = "12px Inter, Arial";
      labels.forEach((label, i) => {
        const y = pad + i * rowH + rowH * .25;
        const available = w - labelW - pad * 2;
        const barW = values[i] / max * available;
        ctx.fillStyle = "#475569";
        ctx.textAlign = "left";
        ctx.fillText(label, pad, y + 13);
        ctx.fillStyle = "#e2e8f0";
        roundRect(ctx, labelW, y, available, rowH * .42, 8, true);
        ctx.fillStyle = colors[i] || "#0f6fbf";
        roundRect(ctx, labelW, y, Math.max(2, barW), rowH * .42, 8, true);
        if (targets[i]) {
          const tx = labelW + (targets[i] / max) * available;
          ctx.strokeStyle = "#d97706";
          ctx.beginPath();
          ctx.moveTo(tx, y - 3);
          ctx.lineTo(tx, y + rowH * .42 + 3);
          ctx.stroke();
        }
      });
    }

    function drawFunnelChart(canvasId, items) {
      const base = drawBase(canvasId);
      if (!base) return;
      const { ctx, w, h } = base;
      const max = Math.max(1, ...items.map(i => i.value));
      const colors = ["#0f6fbf", "#04a7c4", "#7c3aed", "#d97706", "#16a34a"];
      const pad = 22;
      const rowH = (h - pad * 2) / items.length;
      ctx.font = "12px Inter, Arial";
      items.forEach((item, i) => {
        const width = (item.value / max) * (w - pad * 2);
        const x = (w - width) / 2;
        const y = pad + i * rowH + 5;
        ctx.fillStyle = colors[i % colors.length];
        roundRect(ctx, x, y, width, rowH * .55, 10, true);
        ctx.fillStyle = "#fff";
        ctx.textAlign = "center";
        ctx.fillText(`${item.label}: ${fmtNum(item.value)}`, w / 2, y + rowH * .34);
      });
    }

    function drawSalesChart(companies) {
      drawBarChart("chartSales", companies.map(c => c.short), companies.map(c => aggregateQuotes(filteredQuotes(), [c.id]).closedAmount), companies.map(c => c.monthlyGoal), companies.map(c => c.color));
    }

    function drawPipelineChart(companies) {
      drawHorizontalBarChart("chartPipeline", companies.map(c => c.short), companies.map(c => aggregateQuotes(filteredQuotes(), [c.id]).quotedAmount), companies.map(c => c.monthlyGoal / (state.config.closeRate / 100)), companies.map(c => c.color));
    }

    function drawProspectingChart(companies) {
      const records = filteredProspectingRecords();
      const labels = companies.map(c => c.short);
      const values = companies.map(c => aggregateProspecting(records, [c.id]).emails);
      const targets = companies.map(c => c.vendors.length * state.config.dailyPersonalizedEmails * state.config.workDaysPerWeek * periodMultiplier());
      drawBarChart("chartProspecting", labels, values, targets, companies.map(c => c.color));
    }

    function drawProspectingChannels(records) {
      const p = aggregateProspecting(records);
      drawHorizontalBarChart("chartProspectingChannels", ["Correo", "Llamada", "WhatsApp", "LinkedIn"], [p.emails, p.calls, p.whatsapps, p.linkedin], [], ["#0f6fbf", "#16a34a", "#04a7c4", "#7c3aed"]);
    }

    function drawVendorEmails(records, companies) {
      const totals = {};
      companies.forEach(c => c.vendors.forEach(v => totals[v] = 0));
      records.forEach(r => {
        if (r.channels?.email) totals[r.vendor] = (totals[r.vendor] || 0) + 1;
      });
      const labels = Object.keys(totals).slice(0, 14);
      const values = labels.map(l => totals[l]);
      const targets = labels.map(() => state.config.dailyPersonalizedEmails * state.config.workDaysPerWeek * periodMultiplier());
      drawHorizontalBarChart("chartVendorEmails", labels.length ? labels : ["Sin datos"], values.length ? values : [0], targets.length ? targets : [0], ["#0f6fbf"]);
    }

    function drawResponseRate(companies, records) {
      const labels = companies.map(c => c.short);
      const values = companies.map(c => {
        const p = aggregateProspecting(records, [c.id]);
        return p.records ? p.responses / p.records * 100 : 0;
      });
      drawBarChart("chartResponseRate", labels, values, labels.map(() => 15), companies.map(c => c.color));
    }

    function drawStageChart(leads) {
      const stages = ["Nuevo", "Contactado", "Calificado", "Levantamiento", "Cotizado", "Negociación", "Ganado", "Perdido"];
      const values = stages.map(s => leads.filter(l => l.stage === s).length);
      drawBarChart("chartStages", stages.slice(0,5), values.slice(0,5), [], ["#0f6fbf","#04a7c4","#7c3aed","#d97706","#16a34a"]);
    }

    function drawQuotesChart(quotes) {
      const statuses = ["Enviada", "En seguimiento", "Negociación", "Ganada", "Perdida"];
      const values = statuses.map(s => quotes.filter(q => q.status === s).reduce((sum, q) => sum + quoteAmountMxn(q), 0));
      drawHorizontalBarChart("chartQuotes", statuses, values, [], ["#7c3aed","#0f6fbf","#d97706","#16a34a","#dc2626"]);
    }

    function drawVendorsChart() {
      const companies = filteredCompanies();
      const prospecting = filteredProspectingRecords();
      const labels = [];
      const values = [];
      companies.forEach(c => c.vendors.forEach(v => {
        labels.push(v);
        values.push(prospecting.filter(r => r.vendor === v && r.channels?.email).length);
      }));
      drawHorizontalBarChart("chartVendors", labels.slice(0,14), values.slice(0,14), labels.slice(0,14).map(() => state.config.dailyPersonalizedEmails * state.config.workDaysPerWeek * periodMultiplier()), ["#0f6fbf"]);
    }

    function drawAdsChart() {
      const companies = filteredCompanies();
      const labels = companies.map(c => c.short);
      const leads = filteredLeads();
      const cpl = companies.map(c => {
        const leadCount = leads.filter(l => l.companyId === c.id).length;
        const spend = state.config.adBudgetWeekly * periodMultiplier();
        return leadCount ? spend / leadCount : 0;
      });
      const targets = companies.map(() => state.config.adBudgetWeekly / state.config.leadTargetWeekly);
      drawBarChart("chartAds", labels, cpl, targets, companies.map(c => c.color));
    }

    function bindEvents() {
      document.querySelectorAll(".nav button").forEach(btn => {
        btn.addEventListener("click", () => {
          document.querySelectorAll(".nav button").forEach(b => b.classList.remove("active"));
          btn.classList.add("active");
          document.querySelectorAll(".section").forEach(s => s.classList.remove("active"));
          document.getElementById(`section-${btn.dataset.section}`).classList.add("active");
          setTimeout(renderAll, 70);
        });
      });

      ["filterCompany", "filterPeriod", "filterMonth"].forEach(id => document.getElementById(id).addEventListener("change", renderAll));
      document.getElementById("btnProspect").addEventListener("click", () => document.querySelector('[data-section="prospeccion"]').click());
      document.getElementById("btnRefreshAuto").addEventListener("click", renderAll);
      document.getElementById("btnPrint").addEventListener("click", () => window.print());

      document.getElementById("btnReset").addEventListener("click", async () => {
        if (!confirm("Esto borrará los datos locales y cargará datos demo. ¿Continuar?")) return;
        await resetDatabase();
        state = seedState();
        populateSelects();
        renderAll();
      });

      document.getElementById("btnExport").addEventListener("click", () => {
        const blob = new Blob([JSON.stringify(state, null, 2)], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `erp-comercial-auto-${currentMonth()}.json`;
        a.click();
        URL.revokeObjectURL(url);
      });

      document.getElementById("importFile").addEventListener("change", async (e) => {
        const file = e.target.files[0];
        if (!file) return;
        try {
          const imported = JSON.parse(await file.text());
          state = migrateState({ ...structuredClone(defaultState), ...imported, config: { ...defaultState.config, ...(imported.config || {}) } });
          state.companies = state.companies.map(c => {
            const base = baseCompanies.find(b => b.id === c.id);
            return { ...base, ...c, logo: base ? base.logo : c.logo, services: base ? base.services : c.services };
          });
          populateSelects();
          renderAll();
          alert("Importación completada.");
        } catch (err) {
          alert("No se pudo importar el archivo JSON.");
        }
      });

      document.getElementById("prospectingForm").addEventListener("submit", e => {
        e.preventDefault();
        const rec = {
          id: uid(),
          date: val("pDate"),
          companyId: val("pCompany"),
          vendor: val("pVendor"),
          clientType: val("pClientType"),
          clientCompany: val("pClientCompany"),
          contactName: val("pContactName"),
          position: val("pPosition"),
          phone: val("pPhone"),
          email: val("pEmail"),
          linkedin: val("pLinkedin"),
          service: val("pService"),
          channels: {
            email: document.getElementById("pChEmail").checked,
            call: document.getElementById("pChCall").checked,
            whatsapp: document.getElementById("pChWhats").checked,
            linkedin: document.getElementById("pChLinkedin").checked
          },
          result: val("pResult"),
          generatedLead: val("pGeneratedLead") === "yes",
          nextAction: val("pNextAction"),
          priority: val("pPriority"),
          notes: val("pNotes")
        };
        state.prospectingRecords.push(rec);

        if (rec.generatedLead) {
          state.leads.push({
            id: uid(),
            date: rec.date,
            companyId: rec.companyId,
            vendor: rec.vendor,
            client: rec.clientCompany,
            contactName: rec.contactName,
            source: "Prospección B2B",
            stage: "Nuevo",
            interestType: serviceToInterestType(rec.service),
            service: rec.service.replace(/^Servicio - /, "").replace(/^Producto - /, "").replace(/^Producto en venta - /, "").replace(/^Renta - /, ""),
            nextAction: rec.nextAction,
            priority: rec.priority,
            notes: `Generado desde prospección. Resultado: ${rec.result}.`
          });
        }

        e.target.reset();
        document.getElementById("pDate").value = today();
        document.getElementById("pChEmail").checked = true;
        updateVendorSelect("pCompany", "pVendor");
        setServiceOptions("pCompany", "pService");
        renderAll();
        alert("Prospección B2B guardada.");
      });

      document.getElementById("leadForm").addEventListener("submit", e => {
        e.preventDefault();
        state.leads.push({
          id: uid(),
          date: val("lDate"),
          companyId: val("lCompany"),
          vendor: val("lVendor"),
          client: val("lClient"),
          contactName: val("lContactName"),
          source: val("lSource"),
          stage: val("lStage"),
          interestType: val("lInterestType"),
          service: val("lService"),
          nextAction: val("lNextAction"),
          priority: val("lPriority"),
          notes: val("lNotes")
        });
        e.target.reset();
        document.getElementById("lDate").value = today();
        updateVendorSelect("lCompany", "lVendor");
        setLeadServiceOptions("lCompany", "lInterestType", "lService");
        renderAll();
      });

      document.getElementById("quoteForm").addEventListener("submit", e => {
        e.preventDefault();
        state.quotes.push({
          id: uid(),
          date: val("qDate"),
          companyId: val("qCompany"),
          vendor: val("qVendor"),
          folio: val("qFolio"),
          client: val("qClient"),
          service: val("qService"),
          quoteName: val("qQuoteName"),
          amount: num("qAmount"),
          currency: val("qCurrency"),
          status: val("qStatus"),
          notes: val("qNotes")
        });
        e.target.reset();
        document.getElementById("qDate").value = today();
        updateVendorSelect("qCompany", "qVendor");
        setServiceOptions("qCompany", "qService");
        renderAll();
      });

      document.getElementById("configForm").addEventListener("submit", e => {
        e.preventDefault();
        state.config.closeRate = num("cfgCloseRate");
        state.config.weeksPerMonth = num("cfgWeeksMonth");
        state.config.leadTargetWeekly = num("cfgLeadTarget");
        state.config.quoteTargetWeekly = num("cfgQuoteTarget");
        state.config.adBudgetWeekly = num("cfgAdBudget");
        state.config.dailyPersonalizedEmails = num("cfgDailyEmails");
        state.config.workDaysPerWeek = num("cfgWorkDays");
        state.config.exchangeRateUsdMxn = num("cfgExchangeRate");
        renderAll();
        alert("Configuración guardada.");
      });

      document.getElementById("goalsForm").addEventListener("submit", e => {
        e.preventDefault();
        document.querySelectorAll("[data-goal]").forEach(input => {
          const c = companyById(input.dataset.goal);
          c.monthlyGoal = Number(input.value || 0);
        });
        renderAll();
        alert("Metas actualizadas.");
      });

      ["pCompany","lCompany","qCompany"].forEach(id => {
        const vendorId = id === "pCompany" ? "pVendor" : id === "lCompany" ? "lVendor" : "qVendor";
        const serviceId = id === "pCompany" ? "pService" : id === "lCompany" ? "lService" : "qService";
        document.getElementById(id).addEventListener("change", () => {
          updateVendorSelect(id, vendorId);
          if (id === "lCompany") {
            setLeadServiceOptions("lCompany", "lInterestType", "lService");
          } else {
            setServiceOptions(id, serviceId);
          }
        });
      });
      document.getElementById("lInterestType").addEventListener("change", () => {
        setLeadServiceOptions("lCompany", "lInterestType", "lService");
      });

      window.addEventListener("resize", debounce(renderAll, 180));
    }

    function debounce(fn, wait) {
      let t;
      return (...args) => {
        clearTimeout(t);
        t = setTimeout(() => fn.apply(null, args), wait);
      };
    }

    async function initERP() {
      state = await loadState();
      populateSelects();
      bindEvents();
      renderAll();
    }

    initERP();

    window.deleteProspecting = deleteProspecting;
    window.deleteLead = deleteLead;
    window.deleteQuote = deleteQuote;
  </script>
</body>
</html>
